CREATE OR REPLACE FUNCTION public.combat_v2_step_end(p_state jsonb, p_b jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  b jsonb := coalesce(p_b, combat_v2_status_numbers()); ss jsonb := b->'v2_status';
